<template>
  <!-- <v-parallax
    src="@/assets/bg.jpg"
  > -->
  <div :style="{'backgroundImage': 'url(' + image + ')', height: '100%', backgroundPosition: 'center'}">
  <v-container style="height:70vh, width: 70vw">
    <v-row justify="center" align="center" class="mt-5">
      <v-col md="12" class="d-flex justify-center">
          <v-img contain :max-width="width" src="@/assets/artistic.jpeg" class="rounded-circle" style="border: 1vw solid #f6c543;"/>
      </v-col>
    </v-row>
    <v-row justify="center" align="center" class="mt-10">
      <div :class="titleSize + ' font-weight-bold'">Agustín Roca</div>
    </v-row>
    <v-row justify="center" align="center" class="mt-5">
      <div :class="subtitleSize">{{$t('message.software_engineer')}} - {{$t('message.ai_enthusiast')}}</div>
    </v-row>
  </v-container>
</div>
  <!-- </v-parallax> -->
</template>

<script>
import { defineComponent } from 'vue';
import { useDisplay } from 'vuetify'
import { computed } from 'vue'

// Components

export default defineComponent({
  name: 'HomeView',
  data () {
    return {
      image: require('../assets/bg.jpg')
    }
  },

  setup () {
    const { name } = useDisplay()

    const width = computed(() => {
      // name is reactive and
      // must use .value
      switch (name.value) {
        case 'xs': return 200
        case 'sm': return 250
        case 'md': return 300
        case 'lg': return 400
        case 'xl': return 600
        case 'xxl': return 600
      }

      return undefined
    })

    const titleSize = computed(() => {
      // name is reactive and
      // must use .value
      switch (name.value) {
        case 'xs': return 'text-h3'
        case 'sm': return 'text-h3'
        case 'md': return 'text-h2'
        case 'lg': return 'text-h1'
        case 'xl': return 'text-h1'
        case 'xxl': return 'text-h1'
      }

      return undefined
    })

    const subtitleSize = computed(() => {
      // name is reactive and
      // must use .value
      switch (name.value) {
        case 'xs': return 'text-h6'
        case 'sm': return 'text-h4'
        case 'md': return 'text-h3'
        case 'lg': return 'text-h2'
        case 'xl': return 'text-h2'
        case 'xxl': return 'text-h2'
      }

      return undefined
    })

    return { width, titleSize, subtitleSize }
  }
});
</script>
